#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <inttypes.h>

/* Compute (base^exp) mod mod, where 0 <= exp and mod > 0.
   Uses 128‑bit arithmetic to avoid overflow. */
static long long mod_pow(long long base, long long exp, long long mod)
{
    long long result = 1 % mod;          /* works even when mod == 1 */
    base %= mod;
    if (base < 0)
        base += mod;                     /* make base non‑negative */

    while (exp > 0) {
        if (exp & 1LL) {
            __int128 tmp = (__int128)result * base;
            result = (long long)(tmp % mod);
        }
        __int128 sq = (__int128)base * base;
        base = (long long)(sq % mod);
        exp >>= 1LL;
    }
    return result;
}

/* Helper that checks whether the whole string was consumed by strtoll. */
static int parse_number(const char *s, long long *out)
{
    char *endptr;
    *out = strtoll(s, &endptr, 10);
    return (*endptr == '\0');   /* true iff the whole string is a valid number */
}

int main(int argc, char **argv)
{
    long long base, exp, mod;

    if (argc < 4) {
        puts("NO_INPUT");
        return 0;
    }

    if (!parse_number(argv[1], &base) ||
        !parse_number(argv[2], &exp) ||
        !parse_number(argv[3], &mod)) {
        puts("BAD_INPUT");
        return 0;
    }

    if (mod < 1) {
        puts("BAD_MODULUS");
        return 0;
    }

    if (mod > 1000000000LL) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    if (exp < 0) {
        puts("NEGATIVE_EXPONENT");
        return 0;
    }

    long long result = mod_pow(base, exp, mod);
    printf("result=%" PRId64 "\n", result);
    return 0;
}
